//! AVX10.2 in the 64-bit x86 language (avx10_2.sinc, generated by
//! tools/gen_x86_avx10.py from LLVM's X86 TableGen records): BF16 arithmetic,
//! FP8 conversions, saturating conversions, VMINMAX, VCOMX/VUCOMX, VMPSADBW,
//! the EVEX VNNI-INT8/INT16 dot products, VMOVRS, SM4 and the AMX-AVX512 row
//! moves. Before, each was a bad instruction.
use crate::common;
use common::{repo_root, run_unlace};

fn fixture(name: &str) -> String {
    repo_root()
        .join("crates/unlace-cli/tests/fixtures/x86_avx10")
        .join(name)
        .to_str()
        .unwrap()
        .to_owned()
}

fn rows(stdout: &str) -> Vec<String> {
    stdout
        .lines()
        .filter(|line| line.starts_with("0x"))
        .map(|line| {
            line.split_whitespace()
                .skip(2)
                .collect::<Vec<_>>()
                .join(" ")
        })
        .collect()
}

#[test]
fn avx10_probe_matches_llvm() {
    let elf = fixture("avx10.elf");
    let (stdout, stderr, code) = run_unlace(&["disassemble", &elf, "probe"]);
    assert_eq!(code, 0, "{stderr}");
    let want = std::fs::read_to_string(fixture("probe.txt")).unwrap();
    let want: Vec<&str> = want.lines().collect();
    let got = rows(&stdout);
    assert_eq!(got.len(), want.len(), "{stdout}");
    for (i, (g, w)) in got.iter().zip(&want).enumerate() {
        assert_eq!(g, w, "row {i}");
    }
}

fn decompile(func: &str) -> String {
    let elf = fixture("avx10.elf");
    let (stdout, stderr, code) = run_unlace(&["decompile", &elf, func]);
    assert_eq!(code, 0, "{func}: {stderr}");
    let lower = stdout.to_lowercase();
    assert!(!lower.contains("unimplemented"), "{func}:\n{stdout}");
    assert!(!lower.contains("bad instruction"), "{func}:\n{stdout}");
    stdout
}

#[test]
fn avx10_functions_decompile() {
    // vcomxsd sets OF SF ZF PF CF so that seta is an ordered greater-than
    let out = decompile("gt");
    assert!(out.contains("return a1 < a0;"), "{out}");
    // vmovrsd with {k1}{z} loads the masked elements, Disp8*64 scales the offset
    let out = decompile("mvrs");
    assert!(out.contains("((int *)a0)[0x10]"), "{out}");
    let out = decompile("cvt");
    assert!(out.contains("avx10_vcvttsd2sis("), "{out}");
    let out = decompile("mm");
    assert!(out.contains("avx10_vminmaxpd("), "{out}");
}

const BASE_FIXES: [&str; 11] = [
    "VPBROADCASTQ ZMM25, R10",
    "VPBROADCASTB XMM1{K1}, EAX",
    "VADDPS ZMM1, ZMM2, dword ptr [RAX + 0x4]{1to16}",
    "VADDPD YMM1, YMM2, qword ptr [RAX + 0x8]{1to4}",
    "VPGATHERDD ZMM0{K1}, dword ptr [RAX + ZMM17*0x4 + 0x40]",
    "VGATHERQPD YMM3{K2}, qword ptr [R9 + YMM30*0x8]",
    "VPSCATTERQD dword ptr [RAX + ZMM20*0x4 + 0x8]{K1}, YMM18",
    "VADDPH ZMM1 , ZMM2, word ptr [RAX + 0x2]{1to32}",
    "VCVTPH2PD ZMM1, xmmword ptr [RAX + 0x20]",
    "VCVTPH2QQ ZMM1{K1}, word ptr [RAX + 0x2]{1to8}",
    "RET",
];

/// AVX-512 decode fixes in the base spec: the GPR source of VPBROADCASTB/W/D/Q,
/// the {1toN} broadcast marker, the vector index (and EVEX.V' bank) of the
/// gathers and scatters, and Disp8*N with a 16-bit broadcast element.
#[test]
fn avx512_base_fixes_match_llvm() {
    let elf = fixture("base_fixes.elf");
    let (stdout, stderr, code) = run_unlace(&["disassemble", &elf, "base_fixes"]);
    assert_eq!(code, 0, "{stderr}");
    assert_eq!(rows(&stdout), BASE_FIXES, "{stdout}");
}
